template <typename T>
void do_not_optimize(const T& value) {
    asm volatile("" : : "r,m"(value) : "memory");
}

template <typename F>
double bench(F&& fn, int iterations) {
    auto start = std::chrono::steady_clock::now();
    for (int i = 0; i < iterations; ++i) {
        auto result = fn();
        do_not_optimize(result);
    }
    auto elapsed = std::chrono::steady_clock::now() - start;
    return std::chrono::duration<double, std::nano>(elapsed).count() / iterations;
}

int demo() {
    int x = 0;
    double ns = bench([&] { return ++x; }, 1000);
    return static_cast<int>(ns >= 0.0) + x;
}

int classify(int x) {
    if (x < 0) [[unlikely]] {
        return -1;
    } else if (x == 0) [[unlikely]] {
        return 0;
    }
    return 1;
}

int branchless_max(int a, int b) {
    int diff = a - b;
    int mask = diff >> 31;
    return b + (diff & ~mask);
}

int branchless_select(bool cond, int a, int b) {
    return b ^ ((-static_cast<int>(cond)) & (a ^ b));
}

int demo() {
    return classify(-5) + classify(0) + classify(9)
         + branchless_max(3, 7) + branchless_select(true, 10, 20);
}

