#include <atomic>

template <typename T>
class SeqLock {
public:
    void write(const T& value) {
        seq_.fetch_add(1, std::memory_order_acq_rel);
        value_ = value;
        seq_.fetch_add(1, std::memory_order_release);
    }

    T read() const {
        T copy;
        unsigned before, after;
        do {
            before = seq_.load(std::memory_order_acquire);
            copy = value_;
            after = seq_.load(std::memory_order_acquire);
        } while (before != after || (before & 1));
        return copy;
    }

private:
    std::atomic<unsigned> seq_{0};
    T value_{};
};

int demo() {
    SeqLock<int> lock;
    lock.write(41);
    int a = lock.read();
    lock.write(a + 1);
    return lock.read();
}

#include <xmmintrin.h>

void add_arrays(const float* a, const float* b, float* out, int n) {
    int i = 0;
    for (; i + 4 <= n; i += 4) {
        __m128 va = _mm_loadu_ps(a + i);
        __m128 vb = _mm_loadu_ps(b + i);
        _mm_storeu_ps(out + i, _mm_add_ps(va, vb));
    }
    for (; i < n; ++i) out[i] = a[i] + b[i];
}

float horizontal_sum(__m128 v) {
    __m128 shuf = _mm_shuffle_ps(v, v, _MM_SHUFFLE(2, 3, 0, 1));
    __m128 sums = _mm_add_ps(v, shuf);
    shuf = _mm_movehl_ps(shuf, sums);
    sums = _mm_add_ss(sums, shuf);
    return _mm_cvtss_f32(sums);
}

int demo() {
    float a[6] = {1, 2, 3, 4, 5, 6};
    float b[6] = {1, 1, 1, 1, 1, 1};
    float out[6]{};
    add_arrays(a, b, out, 6);
    __m128 v = _mm_setr_ps(1, 2, 3, 4);
    return static_cast<int>(out[5]) + static_cast<int>(horizontal_sum(v));
}

#include <xmmintrin.h>

void clamp_positive(float* data, int n) {
    __m128 zero = _mm_setzero_ps();
    int i = 0;
    for (; i + 4 <= n; i += 4) {
        __m128 v = _mm_loadu_ps(data + i);
        __m128 mask = _mm_cmpgt_ps(v, zero);
        __m128 result = _mm_or_ps(_mm_and_ps(mask, v), _mm_andnot_ps(mask, zero));
        _mm_storeu_ps(data + i, result);
    }
}

int demo() {
    float data[4] = {-1.0f, 2.0f, -3.0f, 4.0f};
    clamp_positive(data, 4);
    return static_cast<int>(data[0] + data[1] + data[2] + data[3]);
}

